import{_ as t,o as s,c as a,ae as n}from"./chunks/framework.DQC_QtFV.js";const p=JSON.parse('{"title":"Schedules","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/console/schedules.md","filePath":"en/guide/console/schedules.md","lastUpdated":1793162416000}'),o={name:"en/guide/console/schedules.md"};function r(i,e,d,l,h,c){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="schedules" tabindex="-1">Schedules <a class="header-anchor" href="#schedules" aria-label="Permalink to &quot;Schedules&quot;">​</a></h1><p>The schedules page lists the timed tasks, read and cancel only - the tasks are written by the assistant itself from a script in an admin&#39;s private chat, and nothing here creates or edits one.</p><p>One row per task: the conversation it fires in, when it is next due, its repeat rule, the note its turn carries, and what its last run did.</p><ul><li><strong>已触发</strong> (ran): that turn started.</li><li><strong>已跳过</strong> (skipped): the occurrence was dropped by the conversation policy or the catch-up rule, with the reason beside it (for example &quot;说话方式为不说话&quot;).</li><li><strong>未触发</strong> (not yet): before the task&#39;s first run.</li></ul><p>The repeat rule shows the interval and weekdays, the runs left and the stop time; a one-off task has none of these. To stop a task, cancel it - that turn simply never comes, and nothing else changes.</p><p>A <code>wait</code> (one minute to one day) is not here: that is the assistant saying &quot;look again in a while&quot; inside a turn, at most ten in a row, and it survives a restart.</p>',6)])])}const _=t(o,[["render",r]]);export{p as __pageData,_ as default};
